function(container, apiUrl, tables) {
  // エラー情報の初期化
  const errorInfo = {
    title: "システムエラーが発生しました",
    message: "申し訳ございませんが、システムで予期しないエラーが発生しました。",
    code: "ERR_500_001",
    timestamp: new Date().toLocaleString('ja-JP', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit'
    }).replace(/\//g, '/'),
    solution: [
      "1. 「再試行」ボタンをクリックして、もう一度お試しください",
      "2. 問題が解決しない場合は、ページを再読み込みしてください", 
      "3. それでも解決しない場合は、管理者にお問い合わせください"
    ],
    details: {
      url: window.location.pathname,
      method: "POST",
      status: "500",
      userAgent: navigator.userAgent.substring(0, 50) + "...",
      stack: "TypeError: Cannot read property 'id' of undefined\n    at WorkRecordService.save (work-record.service.js:45)\n    at async saveWorkRecord (work-record.controller.js:23)"
    }
  };

  // URLパラメータからエラー情報を取得（もしあれば）
  const urlParams = new URLSearchParams(window.location.search);
  if (urlParams.get('error')) {
    try {
      const errorData = JSON.parse(decodeURIComponent(urlParams.get('error')));
      Object.assign(errorInfo, errorData);
    } catch (e) {
      console.warn('エラー情報の解析に失敗しました:', e);
    }
  }

  // エラー情報を画面に反映
  container.querySelector('#error-title').textContent = errorInfo.title;
  container.querySelector('#error-message').textContent = errorInfo.message;
  container.querySelector('#error-code').textContent = errorInfo.code;
  container.querySelector('#error-timestamp').textContent = errorInfo.timestamp;

  // 対処方法の更新
  const solutionContainer = container.querySelector('#error-solution-text');
  solutionContainer.innerHTML = errorInfo.solution.map(step => 
    `<p style="margin: 0 0 6px 0;">${step}</p>`
  ).join('');

  // エラー詳細情報の更新
  container.querySelector('#error-url').textContent = errorInfo.details.url;
  container.querySelector('#error-method').textContent = errorInfo.details.method;
  container.querySelector('#error-status').textContent = errorInfo.details.status;
  container.querySelector('#error-user-agent').textContent = errorInfo.details.userAgent;
  container.querySelector('#error-stack').textContent = errorInfo.details.stack;

  // 再試行ボタン
  container.querySelector('#btn-retry').addEventListener('click', () => {
    // 前の画面に戻って再実行を試みる
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  // 戻るボタン
  container.querySelector('#btn-back').addEventListener('click', () => {
    if (window.history.length > 1) {
      window.history.back();
    } else {
      window.showScreen('scr-1778907133295'); // 工数記録画面
    }
  });

  // ホームに戻るボタン
  container.querySelector('#btn-home').addEventListener('click', () => {
    window.showScreen('scr-1778907133295'); // 工数記録画面（メイン画面）
  });

  // 管理者に連絡ボタン
  container.querySelector('#btn-contact').addEventListener('click', () => {
    // 緊急報告画面に遷移してエラー情報を引き継ぐ
    const errorReport = {
      type: 'システムエラー',
      code: errorInfo.code,
      message: errorInfo.message,
      timestamp: errorInfo.timestamp,
      details: JSON.stringify(errorInfo.details, null, 2)
    };

    // 緊急報告画面にエラー情報をセッションストレージで渡す
    sessionStorage.setItem('errorReport', JSON.stringify(errorReport));
    window.showScreen('scr-1778907330826'); // 緊急報告画面
  });

  // エラー詳細表示切り替え
  const toggleDetailsBtn = container.querySelector('#btn-toggle-details');
  const detailsSection = container.querySelector('#error-details');
  let detailsVisible = false;

  toggleDetailsBtn.addEventListener('click', () => {
    detailsVisible = !detailsVisible;
    if (detailsVisible) {
      detailsSection.classList.remove('hidden');
      toggleDetailsBtn.textContent = 'エラー詳細を非表示';
    } else {
      detailsSection.classList.add('hidden');
      toggleDetailsBtn.textContent = 'エラー詳細を表示';
    }
  });

  // エラーログの記録（異常値検出ログテーブルに保存）
  const saveErrorLog = async () => {
    try {
      const currentUser = JSON.parse(sessionStorage.getItem('currentUser') || '{}');
      const errorLog = {
        検出対象テーブル: 'システムエラー',
        検出対象レコードID: 'system-error-' + Date.now(),
        ユーザーID: currentUser.ユーザーID || 'unknown',
        異常値種別: 'システムエラー',
        検出項目: 'エラーコード',
        検出値: errorInfo.code,
        閾値: 'N/A',
        重要度: '高',
        確認状況: '未確認',
        通知送信フラグ: true,
        検出日時: new Date().toISOString(),
        作成日時: new Date().toISOString(),
        更新日時: new Date().toISOString()
      };

      // 異常値検出ログテーブル（テーブルインデックス4）に保存
      await window.aivicApi.save(4, errorLog);
    } catch (e) {
      console.warn('エラーログの保存に失敗しました:', e);
    }
  };

  // 初期化時にエラーログを保存
  saveErrorLog();

  // キーボードショートカット
  document.addEventListener('keydown', (e) => {
    if (e.key === 'Escape') {
      container.querySelector('#btn-back').click();
    } else if (e.key === 'Enter' && e.ctrlKey) {
      container.querySelector('#btn-retry').click();
    }
  });
}
